# Settings of the DSpark drafter experiment that is ON-POLICY for the Nemotron-Terminal-fine-tuned Qwen3-0.6B (the SFT model on the Hub,
# pipelines/sft/experiments/sft_qwen3_0_6b_nemotron-terminal-corpus): the responses are regenerated by THAT model, turn by turn, on the same
# 100k conversations, and the drafter is trained against its hidden states. Sibling of ../dspark_qwen3_0_6b_nemotron-terminal-corpus_onpolicy
# (the same pipeline for the base model): everything is the same except the target model. Compare with
# ../dspark_qwen3_0_6b-sft-nemotron-terminal-corpus_nemotron-terminal-corpus_offpolicy (same target, corpus completions instead).
# Sourced after env.sh (needs PROJECT_ROOT). Override from the environment:
#   REGEN_LIMIT=300 WORK_DIR=$PROJECT_ROOT/runs/test MAX_STEPS=10 bash vista/run.sh
# Performance-only knobs (concurrency, GPU memory) may differ per machine; everything that changes what
# is trained (dataset, sampling, DSpark settings) must stay the same everywhere.
SPEC_DIR=${SPEC_DIR:-$PROJECT_ROOT/speculators}
MAX_STEPS=${MAX_STEPS:-}         # smoke runs only: stop training after this many steps (empty = full epoch)
# The target: the SFT model on the Hub (public); not pinned to a commit (the tools used here take only a model id): the commit this was built
# against is in NOTES.md. A local path of the same model also works.
MODEL=${MODEL:-atutej/sft_qwen3_0_6b_nemotron-terminal-corpus-20261011}
TARGET_DTYPE=bfloat16            # the SFT model is saved in float32; vLLM would pick another dtype for it, Qwen3 runs in bf16
DATASET="nemotron-terminal"      # preset in speculators' DATASET_CONFIGS (nvidia/Nemotron-Terminal-Corpus)
SUBSET=""                        # "" = the preset default (dataset_adapters); or skill_based_{easy,medium,mixed}
SAMPLE_SEED=0                    # seed of the step-0 random sample
REGEN_LIMIT=${REGEN_LIMIT:-100000}               # conversations to sample and regenerate (dataset_adapters has ~226k)
WORK_DIR=${WORK_DIR:-$PROJECT_ROOT/runs/nemotron_qwen3_0_6b_sft_regen_online_think_mooncake_100k}
SOURCE_FILE="$WORK_DIR/source/${DATASET}${SUBSET:+_$SUBSET}_${REGEN_LIMIT}_seed${SAMPLE_SEED}.jsonl"   # step 0 output
# The base-model on-policy experiment's export of the same sample: linked instead of re-exported, so every drafter experiment uses the SAME
# conversations.
SHARED_SOURCE_FILE=${SHARED_SOURCE_FILE:-$PROJECT_ROOT/runs/nemotron_qwen3_0_6b_regen_online_think_mooncake_100k/source/${DATASET}${SUBSET:+_$SUBSET}_${REGEN_LIMIT}_seed${SAMPLE_SEED}.jsonl}
REGEN_FILE="$WORK_DIR/regen/nemotron_qwen3_0_6b_sft.jsonl"   # step 1 output (regenerated by the SFT model)
DATA_DIR="$WORK_DIR/data"        # step 2 output; kept separate because prepare-data
                                 # --overwrite refuses directories holding other files
CKPT_DIR="$WORK_DIR/checkpoints"
LOG_DIR="$WORK_DIR/logs"
VLLM_PORT=8000
MOONCAKE_PORT=50051              # hidden states move through Mooncake's in-RAM store, not files
MOONCAKE_GLOBAL_GIB=4
MOONCAKE_LOCAL_GIB=2
GPU_MEM_UTIL=0.9                 # assumes the GPUs are (almost) free; lower it if other jobs share them

# Generation settings -- match how you will SERVE the model.
ENABLE_THINKING="true"           # "true" if you serve Qwen3 with thinking on
MAX_GEN_TOKENS=8192              # (the SFT model writes longer answers than the base model: in the rollout eval 28% of first turns and 13% of
                                 # later turns hit 8192, so more conversations are cut short than with the base model) per-request max_tokens; also stops a conversation once its
                                 # total length passes this (regenerate-responses behaviour).
                                 # = SEQ_LENGTH: longer rows would be clipped by prepare-data anyway
REGEN_MAX_MODEL_LEN=32768        # Qwen3-0.6B native context. Must exceed prompt + MAX_GEN_TOKENS, and
                                 # a prompt can pass MAX_GEN_TOKENS once the next terminal-output turn
                                 # is appended; 12288 failed ~15% of conversations with HTTP 400
REGEN_CONCURRENCY=${REGEN_CONCURRENCY:-512}            # scale with NUM_ALL_GPUS so every replica stays busy
MAX_ERROR_FRAC=0.02              # abort if more conversations than this fail

# Training settings (from the official DSpark Qwen3-0.6B example)
SEQ_LENGTH=${SEQ_LENGTH:-8192}                  # training rows longer than this are clipped by prepare-data
SPECULATOR_TYPE="dspark"
EPOCHS=1
LR=3e-4
BLOCK_SIZE=8                     # tokens drafted per step
MAX_ANCHORS=${MAX_ANCHORS:-3072}
NUM_LAYERS=3
TARGET_LAYER_IDS="2 14 25"       # Qwen3-0.6B has 28 layers; launch_vllm.py also appends layer 28
DRAFT_VOCAB_SIZE=32000           # reduced vocab: a full 152K head would dwarf a 3-layer draft
                                 # for this small model. Set to "" to use the full vocabulary.
MARKOV_RANK=256
MARKOV_HEAD_TYPE="vanilla"       # vanilla | gated | rnn
LOSS_FN='{"ce": 0.1, "tv": 0.9}'
CONFIDENCE_HEAD_ALPHA=1.0


# ---- derived ----
if [[ "$ENABLE_THINKING" == "true" ]]; then   # Qwen3's recommended sampling per mode
    SAMPLING_PARAMS='{"temperature": 0.6, "top_p": 0.95, "top_k": 20, "chat_template_kwargs": {"enable_thinking": true}}'
else
    SAMPLING_PARAMS='{"temperature": 0.7, "top_p": 0.8, "top_k": 20, "chat_template_kwargs": {"enable_thinking": false}}'
fi
EXPORT_ARGS=()
[[ -n "$SUBSET" ]] && EXPORT_ARGS+=(--subset "$SUBSET")
VOCAB_ARGS=()
[[ -n "$DRAFT_VOCAB_SIZE" ]] && VOCAB_ARGS=(--draft-vocab-size "$DRAFT_VOCAB_SIZE")
# ---- metric logging (the trainer's --logger) ----
# Weights & Biases for real runs; smoke runs (MAX_STEPS set) log nowhere unless LOGGER is given. LOGGER= (empty) turns it off.
if [[ -n "$MAX_STEPS" ]]; then LOGGER=${LOGGER-}; else LOGGER=${LOGGER-wandb}; fi
RUN_NAME=${RUN_NAME:-$(basename "$(dirname "${BASH_SOURCE[0]}")")}   # the experiment's folder name
# Entity and project are set outright, not defaulted: this account's default W&B entity is the team "dogml", not "atutej".
export WANDB_ENTITY=atutej WANDB_PROJECT=marin_speculator
LOGGER_ARGS=()
if [[ -n "$LOGGER" ]]; then LOGGER_ARGS=(--logger "$LOGGER" --run-name "$RUN_NAME" --log-dir "$LOG_DIR/tracker"); fi
TRAIN_EXTRA=()
# An `if`, not `[[ ]] && ...`: as the last command of a sourced file, a failing `[[ ]]` makes `source` return 1 and
# kills any caller running under `set -e` (this killed the first stage whenever MAX_STEPS was unset).
if [[ -n "$MAX_STEPS" ]]; then TRAIN_EXTRA=(--max-steps "$MAX_STEPS"); fi

# ---- upload of the finished drafter to the Hugging Face Hub (best and latest checkpoint; tools/upload_drafter_to_hf.py) ----
# HF_REPO=auto (the default for full runs) names the repo <experiment folder name>-<YYYYMMDD> under the logged-in account, or under
# HF_NAMESPACE=<user or org>; HF_REPO=<namespace>/<name> is explicit; HF_REPO= (empty) turns the upload off. Smoke runs (MAX_STEPS set)
# never upload unless HF_REPO is given. The repo is PUBLIC unless HF_PRIVATE=true. Needs a write token (HF_TOKEN or HUG_TOKEN).
if [[ -n "$MAX_STEPS" ]]; then HF_REPO=${HF_REPO-}; else HF_REPO=${HF_REPO-auto}; fi
HF_NAMESPACE=${HF_NAMESPACE:-}
HF_PRIVATE=${HF_PRIVATE:-false}
if [[ "$HF_REPO" == auto ]]; then HF_REPO="${HF_NAMESPACE:+$HF_NAMESPACE/}$RUN_NAME-${HF_DATE:-$(date +%Y%m%d)}"; fi
HF_DESCRIPTION='ON-POLICY data for the SFT target: the responses to the conversations of nvidia/Nemotron-Terminal-Corpus (a seeded 100k sample) were regenerated turn by turn by the target itself (Qwen3-0.6B fine-tuned on the same corpus), and the drafter is trained on its hidden states.'
